exercise.solution:
function minLenSumAtLeast(nums: number[], target: number): number {
  let lo = 0;
  let sum = 0;
  let best = Infinity;
  for (let hi = 0; hi < nums.length; hi++) {
    sum += nums[hi];
    while (sum >= target) {
      best = Math.min(best, hi - lo + 1);
      sum -= nums[lo];
      lo++;
    }
  }
  return best === Infinity ? 0 : best;
}

