function countProductLess(nums: number[], k: number): number {
  if (k <= 1) return 0;
  let lo = 0;
  let product = 1;
  let count = 0;
  for (let hi = 0; hi < nums.length; hi++) {
    product *= nums[hi];
    while (product >= k) {
      product /= nums[lo];
      lo++;
    }
    count += hi - lo + 1;
  }
  return count;
}

